using System;
using System.IO;
using UnityEditor;
using UnityEngine;
using E = LittleMusicWorld.EditorTools.EditorAssetUtil;

namespace LittleMusicWorld.EditorTools
{
    /// <summary>
    /// Paints the UI's basic shapes as anti-aliased PNG sprites (signed-distance maths, no external art):
    /// pebble buttons with a darker lip, piano keys, circles, soft glows and a music-note glyph.
    /// Output: Assets/Art/UI/Generated. Regenerated by setup; never hand-edited.
    /// </summary>
    public static class UISprites
    {
        public const string Folder = "Assets/Art/UI/Generated";

        public static Sprite Get(string name) => AssetDatabase.LoadAssetAtPath<Sprite>($"{Folder}/{name}.png");

        public static void BuildAll()
        {
            E.EnsureFolder(Folder);
            // Pebble button: rounded rect with a 14px darker bottom lip and a soft top highlight (white = tintable).
            Paint("Pebble", 256, 256, (x, y, w, h) =>
            {
                float d = RoundRect(x, y, w * 0.5f, h * 0.5f + 7, w * 0.5f - 4, h * 0.5f - 11, 56);
                float lip = RoundRect(x, y, w * 0.5f, h * 0.5f - 4, w * 0.5f - 4, h * 0.5f - 4, 56);
                float a = Mathf.Max(Cover(d), Cover(lip));
                float top = Cover(d);
                float shade = top > 0.5f ? 1f : 0.72f;
                float hl = Mathf.Clamp01((y - h * 0.62f) / (h * 0.3f)) * 0.12f * top;
                float v = Mathf.Clamp01(shade + hl);
                return new Color(v, v, v, a);
            }, new Vector4(64, 64, 64, 64));
            Paint("Panel", 256, 256, (x, y, w, h) =>
            {
                float d = RoundRect(x, y, w * 0.5f, h * 0.5f, w * 0.5f - 3, h * 0.5f - 3, 60);
                return new Color(1, 1, 1, Cover(d));
            }, new Vector4(70, 70, 70, 70));
            // White piano key: rounded bottom, square top, a subtle front lip.
            Paint("KeyWhite", 128, 512, (x, y, w, h) =>
            {
                float d = RoundRect(x, y, w * 0.5f, h * 0.5f + 20, w * 0.5f - 2, h * 0.5f + 18, 26);
                float a = Cover(d);
                float lip = y < 26 ? 0.86f : 1f;
                float grad = 0.94f + 0.06f * (y / h);
                float v = lip * grad;
                return new Color(v, v, v * 0.985f, a);
            }, new Vector4(30, 40, 30, 40));
            Paint("KeyBlack", 96, 320, (x, y, w, h) =>
            {
                float d = RoundRect(x, y, w * 0.5f, h * 0.5f + 16, w * 0.5f - 2, h * 0.5f + 14, 18);
                float top = Mathf.Clamp01((y - 24) / 30f);
                float v = 0.75f + 0.25f * top;
                return new Color(v, v, v, Cover(d));
            }, new Vector4(22, 30, 22, 30));
            Paint("Circle", 128, 128, (x, y, w, h) => new Color(1, 1, 1, Cover(Mathf.Sqrt(Sq(x - 64) + Sq(y - 64)) - 61)), Vector4.zero);
            Paint("Ring", 128, 128, (x, y, w, h) =>
            {
                float r = Mathf.Sqrt(Sq(x - 64) + Sq(y - 64));
                return new Color(1, 1, 1, Cover(Mathf.Abs(r - 54) - 7));
            }, Vector4.zero);
            Paint("Glow", 128, 128, (x, y, w, h) =>
            {
                float r = Mathf.Sqrt(Sq(x - 64) + Sq(y - 64)) / 64f;
                float a = Mathf.Clamp01(1f - r);
                return new Color(1, 1, 1, a * a);
            }, Vector4.zero);
            Paint("GlowRect", 128, 128, (x, y, w, h) =>
            {
                float d = RoundRect(x, y, 64, 64, 40, 40, 24);
                float a = Mathf.Clamp01(1f - Mathf.Max(0, d) / 24f);
                return new Color(1, 1, 1, a * a * (d < 0 ? 1f : 1f));
            }, new Vector4(50, 50, 50, 50));
            Paint("Note", 128, 128, NoteGlyph, Vector4.zero);
            Paint("Sparkle", 128, 128, (x, y, w, h) =>
            {
                float dx = Mathf.Abs(x - 64) / 64f, dy = Mathf.Abs(y - 64) / 64f;
                float star = Mathf.Pow(dx, 0.5f) + Mathf.Pow(dy, 0.5f);
                float a = Mathf.Clamp01((1.05f - star) * 3f);
                return new Color(1, 1, 1, a);
            }, Vector4.zero);
            PaintIcons();
            AssetDatabase.Refresh();
            foreach (string n in new[] { "Pebble", "Panel", "KeyWhite", "KeyBlack", "Circle", "Ring", "Glow", "GlowRect", "Note", "Sparkle" })
                ConfigureSprite($"{Folder}/{n}.png");
            foreach (string n in IconNames) ConfigureSprite($"{Folder}/Icon{n}.png");
        }


        public static readonly string[] IconNames =
            { "Play", "Home", "Back", "Gear", "Star", "Lock", "Listen", "Check", "Bell", "Bun", "Sun", "Heart", "Lamb", "Boat", "Up", "Down", "Stop", "Record", "Trash", "Bus" };

        /// <summary>White glyphs (tinted in UI), 160² with soft edges. Simple, bold silhouettes readable at 60 px.</summary>
        private static void PaintIcons()
        {
            const int N = 160;
            float C = N / 2f;
            Func<float, float, float, float, Color> W(Func<float, float, float> sdf) => (x, y, w, h) => new Color(1, 1, 1, Cover(sdf(x, y)));
            Paint("IconPlay", N, N, W((x, y) => Tri(x, y, new Vector2(52, 30), new Vector2(52, 130), new Vector2(132, 80)) - 4), Vector4.zero);
            Paint("IconStop", N, N, W((x, y) => RoundRect(x, y, C, C, 46, 46, 12)), Vector4.zero);
            Paint("IconRecord", N, N, W((x, y) => Mathf.Sqrt(Sq(x - C) + Sq(y - C)) - 50), Vector4.zero);
            Paint("IconHome", N, N, W((x, y) => Mathf.Min(Tri(x, y, new Vector2(24, 82), new Vector2(136, 82), new Vector2(80, 138)) - 3,
                RoundRect(x, y, C, 54, 42, 34, 6))), Vector4.zero);
            Paint("IconBack", N, N, W((x, y) => Mathf.Min(Tri(x, y, new Vector2(22, 80), new Vector2(78, 130), new Vector2(78, 30)) - 3,
                RoundRect(x, y, 100, 80, 40, 16, 8))), Vector4.zero);
            Paint("IconUp", N, N, W((x, y) => Mathf.Min(Tri(x, y, new Vector2(30, 82), new Vector2(130, 82), new Vector2(80, 138)) - 3,
                RoundRect(x, y, 80, 56, 18, 34, 8))), Vector4.zero);
            Paint("IconDown", N, N, W((x, y) => Mathf.Min(Tri(x, y, new Vector2(30, 78), new Vector2(130, 78), new Vector2(80, 22)) - 3,
                RoundRect(x, y, 80, 104, 18, 34, 8))), Vector4.zero);
            Paint("IconGear", N, N, W((x, y) =>
            {
                float a = Mathf.Atan2(y - C, x - C), r = Mathf.Sqrt(Sq(x - C) + Sq(y - C));
                float teeth = 52 + 10 * Mathf.Clamp(Mathf.Cos(a * 8) * 3f, -1f, 1f);
                return Mathf.Max(r - teeth, 20 - r);
            }), Vector4.zero);
            Paint("IconStar", N, N, W((x, y) => Star(x - C, y - C - 4, 66, 28, 5)), Vector4.zero);
            Paint("IconLock", N, N, W((x, y) => Mathf.Min(RoundRect(x, y, C, 58, 46, 38, 10),
                Mathf.Max(Mathf.Abs(Mathf.Sqrt(Sq(x - C) + Sq(y - 96)) - 28) - 9, 92 - y))), Vector4.zero);
            Paint("IconListen", N, N, W((x, y) =>
            {
                float spk = Mathf.Min(RoundRect(x, y, 44, C, 16, 22, 4), Tri(x, y, new Vector2(40, C), new Vector2(84, 128), new Vector2(84, 32)) - 2);
                float r = Mathf.Sqrt(Sq(x - 84) + Sq(y - C));
                float ang = Mathf.Abs(Mathf.Atan2(y - C, x - 84));
                float wave = Mathf.Min(Mathf.Abs(r - 34) - 6, Mathf.Abs(r - 58) - 6);
                wave = Mathf.Max(wave, (ang - 0.75f) * 60f);
                return Mathf.Min(spk, Mathf.Max(wave, 90 - x));
            }), Vector4.zero);
            Paint("IconCheck", N, N, W((x, y) => Mathf.Min(Seg(x, y, 30, 84, 66, 46) - 13, Seg(x, y, 66, 46, 132, 116) - 13)), Vector4.zero);
            Paint("IconBell", N, N, W((x, y) =>
            {
                float body = Mathf.Max(RoundRect(x, y, C, 86, 46, 50, 40), 40 - y);
                float lip = RoundRect(x, y, C, 44, 58, 9, 8);
                float clap = Mathf.Sqrt(Sq(x - C) + Sq(y - 30)) - 13;
                return Mathf.Min(Mathf.Min(body, lip), clap);
            }), Vector4.zero);
            Paint("IconBun", N, N, (x, y, w, h) =>
            {
                float d = Mathf.Sqrt(Sq((x - C) / 1.2f) + Sq(y - 72)) - 50;
                float cross = Mathf.Min(RoundRect(x, y, C, 80, 46, 6, 6), RoundRect(x, y, C, 80, 6, 40, 6));
                float a = Cover(d);
                float v = cross < 0 ? 0.55f : 1f;
                return new Color(v, v, v, a);
            }, Vector4.zero);
            Paint("IconSun", N, N, W((x, y) =>
            {
                float r = Mathf.Sqrt(Sq(x - C) + Sq(y - C)), a = Mathf.Atan2(y - C, x - C);
                float rays = Mathf.Max(r - 70, Mathf.Abs(Mathf.Sin(a * 4)) * r - 7);
                return Mathf.Min(r - 38, Mathf.Max(rays, 48 - r));
            }), Vector4.zero);
            Paint("IconHeart", N, N, W((x, y) =>
            {
                float hx = (x - C) / 62f, hy = (y - 70) / 62f;
                float v = Mathf.Pow(hx * hx + hy * hy - 0.5f, 3) - hx * hx * hy * hy * hy;
                return v * 260f;
            }), Vector4.zero);
            Paint("IconLamb", N, N, W((x, y) =>
            {
                float d = 99f;
                foreach (var b in new[] { (56f, 82f, 24f), (80f, 92f, 26f), (104f, 82f, 24f), (70f, 66f, 22f), (96f, 66f, 22f) })
                    d = Mathf.Min(d, Mathf.Sqrt(Sq(x - b.Item1) + Sq(y - b.Item2)) - b.Item3);
                d = Mathf.Min(d, Mathf.Sqrt(Sq(x - 128) + Sq(y - 96)) - 16);
                d = Mathf.Min(d, Mathf.Min(RoundRect(x, y, 66, 40, 6, 16, 4), RoundRect(x, y, 96, 40, 6, 16, 4)));
                return d;
            }), Vector4.zero);
            Paint("IconBoat", N, N, W((x, y) => Mathf.Min(Mathf.Max(RoundRect(x, y, C, 46, 62, 20, 16), y - 60),
                Mathf.Min(Tri(x, y, new Vector2(84, 66), new Vector2(84, 136), new Vector2(132, 66)) - 2, RoundRect(x, y, 80, 92, 4, 48, 2)))), Vector4.zero);
            Paint("IconBus", N, N, W((x, y) =>
            {
                float body = RoundRect(x, y, C, 86, 66, 38, 14);
                float windows = 99f;
                foreach (float wx in new[] { 44f, 78f, 112f }) windows = Mathf.Min(windows, RoundRect(x, y, wx, 100, 12, 12, 4));
                float wheels = Mathf.Min(Mathf.Sqrt(Sq(x - 48) + Sq(y - 44)) - 17, Mathf.Sqrt(Sq(x - 112) + Sq(y - 44)) - 17);
                float gaps = Mathf.Min(Mathf.Sqrt(Sq(x - 48) + Sq(y - 44)) - 24, Mathf.Sqrt(Sq(x - 112) + Sq(y - 44)) - 24);
                return Mathf.Min(Mathf.Max(Mathf.Max(body, -windows), -gaps), wheels);
            }), Vector4.zero);
            Paint("IconTrash", N, N, W((x, y) => Mathf.Min(Mathf.Max(RoundRect(x, y, C, 66, 40, 44, 8), -RoundRect(x, y, C, 66, 6, 30, 3)),
                Mathf.Min(RoundRect(x, y, C, 118, 54, 7, 4), RoundRect(x, y, C, 128, 16, 8, 4)))), Vector4.zero);
        }

        private static float Seg(float x, float y, float ax, float ay, float bx, float by)
        {
            Vector2 p = new Vector2(x - ax, y - ay), ba = new Vector2(bx - ax, by - ay);
            float h = Mathf.Clamp01(Vector2.Dot(p, ba) / Vector2.Dot(ba, ba));
            return (p - ba * h).magnitude;
        }

        private static float Tri(float x, float y, Vector2 a, Vector2 b, Vector2 c)
        {
            Vector2 p = new Vector2(x, y);
            float d = Mathf.Min(Seg(x, y, a.x, a.y, b.x, b.y), Mathf.Min(Seg(x, y, b.x, b.y, c.x, c.y), Seg(x, y, c.x, c.y, a.x, a.y)));
            float s1 = Cross(b - a, p - a), s2 = Cross(c - b, p - b), s3 = Cross(a - c, p - c);
            bool inside = (s1 >= 0 && s2 >= 0 && s3 >= 0) || (s1 <= 0 && s2 <= 0 && s3 <= 0);
            return inside ? -d : d;
        }

        private static float Cross(Vector2 a, Vector2 b) => a.x * b.y - a.y * b.x;

        private static float Star(float x, float y, float ro, float ri, int n)
        {
            float a = Mathf.Atan2(x, y);
            float r = Mathf.Sqrt(x * x + y * y);
            float seg = Mathf.PI * 2f / n;
            float t = Mathf.Repeat(a, seg) / seg;           // 0..1 within a point
            float edge = Mathf.Lerp(ro, ri, Mathf.Abs(t - 0.5f) * 2f);
            edge = Mathf.Lerp(ri, ro, 1f - Mathf.Abs(t - 0.5f) * 2f);
            return (r - edge) * 0.8f;
        }

        private static Color NoteGlyph(float x, float y, float w, float h)
        {
            // eighth note: tilted oval head, stem, flag
            float hx = x - 46, hy = y - 34;
            float c = Mathf.Cos(-0.45f), s = Mathf.Sin(-0.45f);
            float rx = hx * c - hy * s, ry = hx * s + hy * c;
            float head = Mathf.Sqrt(Sq(rx / 26f) + Sq(ry / 18f)) - 1f;
            float headD = head * 18f;
            float stem = Box(x, y, 69, 72, 6, 42);
            float fx = x - 76, fy = y - 96;
            float flag = Mathf.Sqrt(Sq(fx / 26f) + Sq(fy / 20f)) - 1f;
            float inner = Mathf.Sqrt(Sq((x - 70) / 22f) + Sq((y - 86) / 16f)) - 1f;
            float flagD = Mathf.Max(flag * 18f, -inner * 14f);
            if (x < 70 || y < 72) flagD = 10f;
            float d = Mathf.Min(headD, Mathf.Min(stem, flagD));
            return new Color(1, 1, 1, Cover(d));
        }

        // ------------------------------------------------------------------ SDF helpers
        private static float Sq(float v) => v * v;
        private static float Cover(float d) => Mathf.Clamp01(0.5f - d);

        private static float RoundRect(float x, float y, float cx, float cy, float hw, float hh, float r)
        {
            r = Mathf.Min(r, Mathf.Min(hw, hh));
            float qx = Mathf.Abs(x - cx) - (hw - r), qy = Mathf.Abs(y - cy) - (hh - r);
            float ox = Mathf.Max(qx, 0), oy = Mathf.Max(qy, 0);
            return Mathf.Sqrt(ox * ox + oy * oy) + Mathf.Min(Mathf.Max(qx, qy), 0) - r;
        }

        private static float Box(float x, float y, float cx, float cy, float hw, float hh)
        {
            float qx = Mathf.Abs(x - cx) - hw, qy = Mathf.Abs(y - cy) - hh;
            return Mathf.Sqrt(Sq(Mathf.Max(qx, 0)) + Sq(Mathf.Max(qy, 0))) + Mathf.Min(Mathf.Max(qx, qy), 0);
        }

        private static void Paint(string name, int w, int h, Func<float, float, float, float, Color> f, Vector4 border)
        {
            var tex = new Texture2D(w, h, TextureFormat.RGBA32, false);
            var px = new Color[w * h];
            for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
            {
                // 4x supersampling for smooth edges
                Color acc = Color.clear;
                for (int sy = 0; sy < 2; sy++)
                for (int sx = 0; sx < 2; sx++)
                    acc += f(x + 0.25f + sx * 0.5f, y + 0.25f + sy * 0.5f, w, h);
                px[y * w + x] = acc * 0.25f;
            }
            tex.SetPixels(px);
            tex.Apply();
            File.WriteAllBytes($"{Folder}/{name}.png", tex.EncodeToPNG());
            UnityEngine.Object.DestroyImmediate(tex);
            Borders[name] = border;
        }

        private static readonly System.Collections.Generic.Dictionary<string, Vector4> Borders =
            new System.Collections.Generic.Dictionary<string, Vector4>();

        public static void ConfigureSprite(string path, Vector4? borderOverride = null)
        {
            AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceSynchronousImport);
            var ti = (TextureImporter)AssetImporter.GetAtPath(path);
            if (ti == null) return;
            ti.textureType = TextureImporterType.Sprite;
            ti.spriteImportMode = SpriteImportMode.Single;
            ti.alphaIsTransparency = true;
            ti.mipmapEnabled = false;
            ti.textureCompression = TextureImporterCompression.Uncompressed;
            Vector4 b = borderOverride ?? (Borders.TryGetValue(Path.GetFileNameWithoutExtension(path), out Vector4 bb) ? bb : Vector4.zero);
            ti.spriteBorder = b;
            ti.SaveAndReimport();
        }
    }
}
